// c10_dds_sine_regs.sv: the shell window of course task c10_dds_sine (frequency word, recording of 1200 samples, packed read port).
module c10_dds_sine_regs (
    input  logic        clk,
    input  logic        rst,
    output logic [15:0] led,
    input  logic [6:0]  win_addr,
    input  logic        win_wr,
    input  logic        win_rd,
    input  logic [31:0] win_wdata,
    output logic [31:0] win_rdata
);
    localparam int NS = 1200;
    logic [23:0]        fw_r;
    logic [11:0]        mem [NS];
    logic [10:0]        wptr;
    logic [9:0]         rptr;
    logic [2:0]         rst_cnt;
    logic               go, rec, done, ov;
    logic signed [11:0] od;
    wire                core_rst_n = !rst && (rst_cnt == 3'd0);

    assign led = 16'd0;

    dds u_core (.clk(clk), .rst_n(core_rst_n), .fw(fw_r), .out_valid(ov), .out_data(od));

    always_ff @(posedge clk) begin
        go <= 1'b0;
        if (go) begin rst_cnt <= 3'd2; rec <= 1'b1; done <= 1'b0; wptr <= '0; rptr <= '0; end
        else if (rst_cnt != 3'd0) rst_cnt <= rst_cnt - 3'd1;
        else if (rec && ov) begin
            mem[wptr] <= od;
            wptr <= wptr + 1'b1;
            if (wptr == NS - 1) begin rec <= 1'b0; done <= 1'b1; end
        end
        if (win_wr) begin
            if (win_addr == 7'h00) fw_r <= win_wdata[23:0];
            if (win_addr == 7'h01) go <= 1'b1;
            if (win_addr == 7'h03 || win_addr == 7'h04) rptr <= win_wdata[9:0];
        end
        win_rdata <= 32'd0;
        if (win_rd) begin
            if (win_addr == 7'h00) win_rdata <= {8'd0, fw_r};
            if (win_addr == 7'h02) win_rdata <= {31'd0, done};
            if (win_addr == 7'h03) win_rdata <= {22'd0, rptr};
            if (win_addr == 7'h04) begin
                if (done && rptr < NS / 2) win_rdata <= {4'd0, mem[{rptr, 1'b1}], 4'd0, mem[{rptr, 1'b0}]};
                rptr <= rptr + 1'b1;
            end
        end
        if (rst) begin
            fw_r <= '0; wptr <= '0; rptr <= '0; rst_cnt <= '0; go <= 1'b0; rec <= 1'b0; done <= 1'b0; win_rdata <= 32'd0;
        end
    end
endmodule

// c10_dds_sine_top.sv: board top (Nexys A7-100T, master-XDC port names), test shell DESIGN_ID "DDSN".
// Reference design for course task c10_dds_sine; the shell window is wired to c10_dds_sine_regs.
module c10_dds_sine_top #(
    parameter int          CLKS_PER_BIT   = 868,
    parameter int          TIMEOUT_CYCLES = 100_000,
    parameter logic [31:0] BUILD_STAMP    = 32'h0
) (
    input  logic        CLK100MHZ,
    input  logic        CPU_RESETN,
    output logic [15:0] LED,
    input  logic        UART_TXD_IN,
    output logic        UART_RXD_OUT
);
    logic        clk, rst, win_wr, win_rd;
    logic [6:0]  win_addr;
    logic [31:0] win_wdata, win_rdata;

    assign clk = CLK100MHZ;
    reset_sync u_rst (.clk(clk), .rst_n_async(CPU_RESETN), .rst(rst));

    fpga_shell #(.CLKS_PER_BIT(CLKS_PER_BIT), .TIMEOUT_CYCLES(TIMEOUT_CYCLES),
                 .DESIGN_ID(32'h4444534e), .BUILD_STAMP(BUILD_STAMP)) u_shell (
        .clk(clk), .rst(rst), .uart_rx(UART_TXD_IN), .uart_tx(UART_RXD_OUT),
        .win_addr(win_addr), .win_wr(win_wr), .win_rd(win_rd), .win_wdata(win_wdata), .win_rdata(win_rdata));

    c10_dds_sine_regs u_regs (
        .clk(clk), .rst(rst), .led(LED),
        .win_addr(win_addr), .win_wr(win_wr), .win_rd(win_rd), .win_wdata(win_wdata), .win_rdata(win_rdata));
endmodule

// Part 10 lesson 5 exercise: a direct digital synthesiser: a phase accumulator, a sine look-up table and a registered output.
//
// Every clock: acc <= acc + fw (AW bits, wraps), and out_data <= LUT[top LA bits of the OLD acc]. So out_data on clock k (k = 0 for the first clock
// after reset is released) is LUT[(k * fw mod 2^AW) >> (AW - LA)] and the low AW - LA bits of the phase are thrown away (phase truncation, which
// makes spurs). The table has 2^LA entries of a full cycle: LUT[i] = floor((2^(OW-1) - 1) * sin(2 pi i / 2^LA) + 0.5), signed OW bits. out_valid is
// low in reset and high from the first clock after it. The output frequency is fw / 2^AW times the clock rate. rst_n is synchronous, active low.
module dds #(
    parameter int AW = 24,
    parameter int LA = 8,
    parameter int OW = 12
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic [AW-1:0]        fw,
    output logic                 out_valid,
    output logic signed [OW-1:0] out_data
);
    logic signed [OW-1:0] lut [2**LA];
    logic [AW-1:0] acc;

    initial begin
        for (int i = 0; i < 2**LA; i++)
            lut[i] = OW'($rtoi($floor((2.0**(OW-1) - 1.0) * $sin(6.283185307179586 * i / (2.0**LA)) + 0.5)));
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            acc <= '0; out_valid <= 1'b0; out_data <= '0;
        end else begin
            acc <= acc + fw;
            out_data <= lut[acc[AW-1 -: LA]];
            out_valid <= 1'b1;
        end
    end
endmodule
